// IRRIGATION.1: OpenSprinkler password hash (MD5, 32 hex) read from
// /home/pi/.config/domopi/opensprinkler.md5; kept only in flow context, never logged.
const value = String(msg.payload || "").trim().toLowerCase();
if (/^[0-9a-f]{32}$/.test(value)) {
    flow.set("os_pw", value);
    node.status({fill: "green", shape: "dot", text: "password caricata"});
} else {
    node.status({fill: "red", shape: "ring", text: "password mancante o non valida"});
    node.warn("Irrigazione: file della password OpenSprinkler mancante o non valido");
}
return null;

// IRRIGATION.1: every 10 s (and right after a command) read the whole OpenSprinkler state.
const pw = flow.get("os_pw");
if (!pw) return null;
return {url: "http://192.168.1.3:9003/ja?pw=" + pw, kind: "poll"};

// IRRIGATION.1: OpenSprinkler HTTP response.
// Outputs: 1 = app state (retained JSON), 2 = command result for the app, 3 = poll now,
//          4 = EmonCMS (emon/irrigazione/zona_N every poll, zona_N_durata_s at the end of a run).
const now = Date.now();
if (msg.kind === "command") {
    const result = msg.payload && typeof msg.payload === "object" ? msg.payload.result : null;
    const ok = msg.statusCode === 200 && result === 1;
    if (!ok) node.warn("Irrigazione: OpenSprinkler ha rifiutato " + msg.command + " (HTTP " + msg.statusCode + ", result " + result + ")");
    return [null, {topic: "zara/interface/irrigation/last_command/stat", retain: false,
                   payload: {ok: ok, command: msg.command, result: result, at_ms: now}},
            {kind: "poll-now"}, null];
}

const d = msg.payload;
if (msg.statusCode !== 200 || !d || typeof d !== "object" || !d.settings || !d.status || !d.stations || !d.programs) {
    node.warn("Irrigazione: lettura stato OpenSprinkler non riuscita (HTTP " + msg.statusCode + ")");
    return null;
}
const names = d.stations.snames || [];
const disabled = d.stations.stn_dis || [];
const sn = d.status.sn || [];
const ps = d.settings.ps || [];
const zones = [];
names.forEach((name, i) => {
    if ((disabled[i >> 3] >> (i & 7)) & 1) return;   // station disabled in OpenSprinkler
    zones.push({id: i + 1, name: String(name), running: sn[i] === 1,
                remaining_s: Array.isArray(ps[i]) ? Number(ps[i][1]) || 0 : 0});
});
const programs = (d.programs.pd || []).map((p, i) => ({id: i + 1, name: String(p[5]), enabled: (p[0] & 1) === 1}));
const state = {schema: "domopi.irrigation.v1", controller_enabled: d.settings.en === 1,
               rain_delay: d.settings.rd === 1, rain_delay_until_s: Number(d.settings.rdst) || 0,
               zones: zones, programs: programs};
flow.set("irrigation_state", state);

// EmonCMS: running state every poll, measured duration when a zone stops.
const starts = flow.get("irrigation_starts") || {};
const emon = [];
for (const z of zones) {
    emon.push({topic: "emon/irrigazione/zona_" + z.id, payload: z.running ? 1 : 0});
    if (z.running && !starts[z.id]) starts[z.id] = now;
    if (!z.running && starts[z.id]) {
        emon.push({topic: "emon/irrigazione/zona_" + z.id + "_durata_s", payload: Math.round((now - starts[z.id]) / 1000)});
        delete starts[z.id];
    }
}
flow.set("irrigation_starts", starts);

// App: publish on change, or every 60 s as heartbeat.
const key = JSON.stringify(state);
const last = flow.get("irrigation_last") || {};
let app = null;
if (key !== last.key || now - (last.at || 0) >= 60000) {
    flow.set("irrigation_last", {key: key, at: now});
    app = {topic: "zara/interface/irrigation/state/stat", retain: true, qos: 1,
           payload: Object.assign({}, state, {updated_at_ms: now})};
}
return [app, null, null, emon];

// IRRIGATION.1: app command -> OpenSprinkler HTTP API. Only known zones/programs, 1-60 min.
// Outputs: 1 = HTTP request, 2 = result for the app (zara/interface/irrigation/last_command/stat).
const BASE = "http://192.168.1.3:9003";
const MAX_MINUTES = 60;
const match = /^zara\/interface\/irrigation\/(.+)\/cmd$/.exec(msg.topic || "");
if (!match) return null;
const command = match[1];
const path = command.split("/");
const value = String(msg.payload).trim().toLowerCase();
const state = flow.get("irrigation_state");

function reject(reason) {
    node.warn("Irrigazione: comando " + command + " scartato (" + reason + ")");
    return [null, {topic: "zara/interface/irrigation/last_command/stat", retain: false,
                   payload: {ok: false, command: command, reason: reason, at_ms: Date.now()}}];
}

const pw = flow.get("os_pw");
if (!pw) return reject("password OpenSprinkler non caricata");
if (!state) return reject("stato OpenSprinkler non ancora letto");

let query;
if (path[0] === "zone" && path.length === 3) {
    const id = Number(path[1]);
    if (!state.zones.some(z => z.id === id)) return reject("zona sconosciuta");
    if (path[2] === "start") {
        const minutes = Number(value);
        if (!Number.isInteger(minutes) || minutes < 1 || minutes > MAX_MINUTES) return reject("minuti non validi");
        query = "cm?sid=" + (id - 1) + "&en=1&t=" + minutes * 60;
    } else if (path[2] === "stop") {
        query = "cm?sid=" + (id - 1) + "&en=0";
    } else return reject("azione sconosciuta");
} else if (path[0] === "program" && path.length === 3 && path[2] === "start") {
    const id = Number(path[1]);
    if (!state.programs.some(p => p.id === id)) return reject("programma sconosciuto");
    if (value !== "true") return reject("valore non valido");
    query = "mp?pid=" + (id - 1) + "&uwt=0";
} else if (command === "all/stop") {
    if (value !== "true") return reject("valore non valido");
    query = "cv?rsn=1";
} else if (command === "controller/enabled") {
    if (value !== "true" && value !== "false") return reject("valore non valido");
    query = "cv?en=" + (value === "true" ? 1 : 0);
} else return reject("comando sconosciuto");

return [{url: BASE + "/" + query + "&pw=" + pw, kind: "command", command: command}, null];
